"use strict";
// A small object API whose loader picks its parts with a computed
// require() specifier: scriptc cannot compile that natively (R1.2), so the
// package runs in a Node island. Its objects keep their identity across
// the boundary.
const { createRequire } = require("node:module");
const load = createRequire(__filename);
const parts = ["./lib/format", "./lib/store"].map((p) => load(p));
const [format, store] = parts;

exports.VERSION = "islandkit " + require("./package.json").version;
exports.Store = store.Store;
exports.createStore = (name) => new store.Store(name);
exports.describe = format.describe;
exports.makePoint = (x, y) => ({ x, y });
exports.addPoints = (a, b) => ({ x: a.x + b.x, y: a.y + b.y });
exports.loads = 0;
exports.ping = () => ++exports.loads;
